sys_ws_operation.operation_script:
(function process( /*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // implement resource here

    var userId = request.pathParams.user_name;
    var queryName = request.queryParams.ni_query;





    var userRec = new GlideRecord('sys_user');
    userRec.addEncodedQuery('user_name=' + userId);
    userRec.query();

    if (userRec.next()) {

        var userSysId = userRec.sys_id.toString();
        var name = userRec.name.toString();
    }


    if (!name) {

        var apiError = new sn_ws_err.ServiceError();
        apiError.setStatus(547);
        apiError.setDetail('No user record found for the user_name passed into the ni_info web service resource using the user_name path parameter.');
        apiError.setMessage('User not found');
        response.setError(apiError);

        return;
    }

    var needItData = [];
    var activeTasks = 0;

    var needItReq = new GlideAggregate('x_58872_needit_needit');
    needItReq.addEncodedQuery('stateIN13,14,15,16^u_requested_for=' + userSysId);
    needItReq.addEncodedQuery(queryName);
    needItReq.groupBy('u_request_type');
    needItReq.addAggregate('COUNT');
    needItReq.query();

    while (needItReq.next()) {

        activeTasks += parseInt(needItReq.getAggregate('COUNT'));

        needItData.push({
            "requestType": needItReq.u_request_type.toString(),
            "reqCount": needItReq.getAggregate('COUNT')

        });

    }






    var body = {

        "ActiveNeedItTasks": activeTasks,

        "ActiveNeedItReqOrder": needItData,

        "User": {

            "userSysId": userSysId,
            "userName": name
        }
    };

    response.setBody(body);


})(request, response);
